def evaluateBoolean(expr):
    prec = {'|': 1, '^': 2, '&': 3, '!': 4}
    vals = []
    ops = []

    def apply():
        op = ops.pop()
        if op == '!':
            vals.append(not vals.pop())
        else:
            b = vals.pop()
            a = vals.pop()
            if op == '|':
                vals.append(a or b)
            elif op == '^':
                vals.append(a != b)
            else:
                vals.append(a and b)

    for c in expr:
        if c == 't' or c == 'f':
            vals.append(c == 't')
        elif c == '(' or c == '!':
            ops.append(c)
        elif c == ')':
            while ops[-1] != '(':
                apply()
            ops.pop()
        else:
            while ops and ops[-1] != '(' and prec[ops[-1]] >= prec[c]:
                apply()
            ops.append(c)
    while ops:
        apply()
    return vals[0]
